package tests

import (
	"errors"
	"sync"
	"testing"
	"time"

	"exercise/src/bins"
)

// within fails the test instead of hanging if work does not finish in time.
func within(t *testing.T, d time.Duration, what string, work func()) {
	t.Helper()
	done := make(chan struct{})
	go func() {
		defer close(done)
		work()
	}()
	select {
	case <-done:
	case <-time.After(d):
		t.Fatalf("%s still blocked after %v (deadlock?)", what, d)
	}
}

func newRegistry() *bins.Registry {
	return bins.NewRegistry(map[string]int{"A-01": 100, "A-02": 100, "B-07": 40})
}

func TestMoveBetweenBins(t *testing.T) {
	r := newRegistry()
	if err := r.Move("A-01", "B-07", 30); err != nil {
		t.Fatal(err)
	}
	a, _ := r.Qty("A-01")
	b, _ := r.Qty("B-07")
	if a != 70 || b != 70 {
		t.Fatalf("A-01=%d B-07=%d, want 70 and 70", a, b)
	}
}

func TestMoveRejectsBadRequests(t *testing.T) {
	r := newRegistry()
	if err := r.Move("B-07", "A-01", 41); !errors.Is(err, bins.ErrInsufficient) {
		t.Fatalf("got %v, want ErrInsufficient", err)
	}
	if err := r.Move("A-01", "Z-99", 1); !errors.Is(err, bins.ErrUnknownBin) {
		t.Fatalf("got %v, want ErrUnknownBin", err)
	}
	if err := r.Move("A-01", "A-02", 0); !errors.Is(err, bins.ErrBadQuantity) {
		t.Fatalf("got %v, want ErrBadQuantity", err)
	}
	if len(r.Movements()) != 0 {
		t.Fatalf("rejected moves must not be logged: %v", r.Movements())
	}
}

func TestOppositeTransfersDoNotDeadlock(t *testing.T) {
	r := newRegistry()
	within(t, 5*time.Second, "opposite transfers", func() {
		var wg sync.WaitGroup
		for _, dir := range [][2]string{{"A-01", "A-02"}, {"A-02", "A-01"}} {
			wg.Add(1)
			go func() {
				defer wg.Done()
				for i := 0; i < 500; i++ {
					_ = r.Move(dir[0], dir[1], 1)
				}
			}()
		}
		wg.Wait()
	})
	if total := r.Total(); total != 240 {
		t.Fatalf("total stock = %d, want 240 (units created or lost)", total)
	}
}

func TestMovesAreLogged(t *testing.T) {
	r := newRegistry()
	_ = r.Move("A-01", "A-02", 5)
	_ = r.Move("B-07", "A-01", 2)
	log := r.Movements()
	if len(log) != 2 || log[0] != (bins.Movement{From: "A-01", To: "A-02", Qty: 5}) {
		t.Fatalf("unexpected movement log: %+v", log)
	}
}

func TestMoveWithinSameBinDoesNotHang(t *testing.T) {
	r := newRegistry()
	var err error
	within(t, 500*time.Millisecond, "move from A-01 to A-01", func() {
		err = r.Move("A-01", "A-01", 10)
	})
	if err != nil {
		t.Fatalf("same-bin move returned %v", err)
	}
	if q, _ := r.Qty("A-01"); q != 100 {
		t.Fatalf("same-bin move changed the quantity to %d, want 100", q)
	}
}

func TestSameBinMoveReleasesTheLock(t *testing.T) {
	r := newRegistry()
	go func() { _ = r.Move("A-02", "A-02", 1) }()
	time.Sleep(50 * time.Millisecond)
	within(t, 500*time.Millisecond, "later transfer out of A-02", func() {
		_ = r.Move("A-02", "B-07", 20)
	})
	if q, _ := r.Qty("B-07"); q != 60 {
		t.Fatalf("B-07 = %d, want 60 after the later transfer", q)
	}
}

func TestStockCountAfterMixedTraffic(t *testing.T) {
	r := newRegistry()
	within(t, 5*time.Second, "mixed traffic", func() {
		var wg sync.WaitGroup
		pairs := [][2]string{{"A-01", "B-07"}, {"B-07", "A-02"}, {"A-02", "A-01"}}
		for _, p := range pairs {
			wg.Add(1)
			go func() {
				defer wg.Done()
				for i := 0; i < 200; i++ {
					_ = r.Move(p[0], p[1], 2)
				}
			}()
		}
		wg.Wait()
	})
	t.Logf("final stock A-01=%d A-02=%d B-07=%d", must(r.Qty("A-01")), must(r.Qty("A-02")), must(r.Qty("B-07")))
	if r.Total() != 240 {
		t.Fatalf("total = %d, want 240", r.Total())
	}
}

func must(n int, err error) int {
	if err != nil {
		panic(err)
	}
	return n
}
